const Docs = () => {
    const safeAriaLabel =
      args.appearance === "icon"
        ? (args["aria-label"] ?? (typeof args.children === "string" ? args.children : "Button"))
        : args["aria-label"];

    if (args.appearance === "solid" || args.appearance === "outline") {
      return (
        <BpButton {...args} aria-label={safeAriaLabel}>
          {args.children}
        </BpButton>
      );
    }

    return (
        <BpButton
            appearance="solid"
            size="large"
            state="default"
            destructive={false}
            loading={false}
            disabled={false}
            icon="ic_add"
            type="button"
            aria-label={safeAriaLabel}>
            {args.appearance === "icon" ? null : args.children}
        </BpButton>
    );
};

