const Gallery = () => {
  // Fixed label column width that comfortably fits the longest annotation text.
  const LABEL_W = 120;
  const ITEM_W = 200;

  const annotation: React.CSSProperties = {
    fontSize: 11,
    color: "var(--text-secondary, #6f6f6f)",
  };

  const cols = ["Default", "Hover", "Selected", "Disabled"];

  const colSpecs: Array<{ state: "default" | "hover"; selected: boolean; disabled: boolean }> = [
    { state: "default", selected: false, disabled: false },
    { state: "hover", selected: false, disabled: false },
    { state: "default", selected: true, disabled: false },
    { state: "default", selected: false, disabled: true },
  ];

  type RowConfig = {
    rowLabel: string;
    selectionMode: "single" | "multi";
    secondaryLabel?: string;
    treeLevel?: "top" | 2 | 3 | 4;
    hasChildren?: boolean;
    treeExpanded?: boolean;
  };

  const sections: Array<{ title: string; rows: RowConfig[] }> = [
    {
      title: "Single",
      rows: [
        { rowLabel: "One-line", selectionMode: "single" },
        {
          rowLabel: "Two-line",
          selectionMode: "single",
          secondaryLabel: "Secondary label",
        },
      ],
    },
    {
      title: "Multi",
      rows: [
        { rowLabel: "One-line", selectionMode: "multi" },
        { rowLabel: "Two-line", selectionMode: "multi", secondaryLabel: "Secondary label" },
      ],
    },
    {
      title: "Tree",
      rows: [
        {
          rowLabel: "Top branch",
          selectionMode: "single",
          treeLevel: "top",
          hasChildren: true,
          treeExpanded: true,
        },
        { rowLabel: "Level 2 leaf", selectionMode: "single", treeLevel: 2 },
        { rowLabel: "Level 3 leaf", selectionMode: "single", treeLevel: 3 },
        {
          rowLabel: "Multi branch",
          selectionMode: "multi",
          treeLevel: 2,
          hasChildren: true,
          treeExpanded: false,
        },
      ],
    },
  ];

  return (
    <div style={{ fontFamily: "var(--font-family)", padding: 24 }}>
      {/* Column headers — offset by the label column so they sit above the item columns */}
      <div style={{ marginLeft: LABEL_W, marginBottom: 8 }}>
        <div style={{ display: "flex", gap: "var(--space-100)" }}>
          {cols.map((col) => (
            <div
              key={col}
              style={{
                width: ITEM_W,
                flexShrink: 0,
                ...annotation,
                fontWeight: 600,
                textAlign: "center",
              }}
            >
              {col}
            </div>
          ))}
        </div>
      </div>

      {/* Mode sections */}
      <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
        {sections.map((section) => (
          <div key={section.title} style={{ display: "flex", flexDirection: "column" }}>
            {/* Section title with underline separator */}
            <div
              style={{
                ...annotation,
                fontWeight: 700,
                letterSpacing: "0.06em",
                textTransform: "uppercase",
                paddingBottom: 4,
                borderBottom: "1px solid var(--border-main, #e0e0e0)",
              }}
            >
              {section.title}
            </div>

            {/* Rows within the section — vertical gap between rows */}
            <div style={{ display: "flex", flexDirection: "column", gap: "var(--space-100)" }}>
              {section.rows.map((row) => (
                <div key={row.rowLabel} style={{ display: "flex", alignItems: "center" }}>
                  {/* Row annotation label — fixed width, right-padded so text stays close to items */}
                  <div
                    style={{
                      width: LABEL_W,
                      flexShrink: 0,
                      ...annotation,
                      paddingLeft: 8,
                      display: "flex",
                      alignItems: "center",
                    }}
                  >
                    {row.rowLabel}
                  </div>

                  {/* Item cells — horizontal gap between columns */}
                  <div style={{ display: "flex", gap: "var(--space-100)" }}>
                    {cols.map((col, colIndex) => {
                      const spec = colSpecs[colIndex];
                      return (
                        <div
                          key={col}
                          role="listbox"
                          aria-label={`${section.title}, ${row.rowLabel}, ${col}`}
                          style={{ width: ITEM_W, flexShrink: 0 }}
                        >
                          <BpDropdownMenuItem
                            label="{Label}"
                            secondaryLabel={row.secondaryLabel}
                            selectionMode={row.selectionMode}
                            state={spec.state}
                            selected={spec.selected}
                            disabled={spec.disabled}
                            treeLevel={row.treeLevel}
                            hasChildren={row.hasChildren}
                            treeExpanded={row.treeExpanded}
                          />
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

