const PaginationGuidelines = function PaginationGuidelinesStory() {
  const [page, setPage] = useState(1);
  const [rows, setRows] = useState<Volume[]>([]);
  const [total, setTotal] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    void fetchVolumesPageMock(page)
      .then((result) => {
        if (cancelled) return;
        setRows(result.items);
        setTotal(result.total);
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [page]);

  const totalPages = Math.max(1, Math.ceil(total / TABLE_PAGE_SIZE));
  const start = total === 0 ? 0 : (page - 1) * TABLE_PAGE_SIZE + 1;
  const end = Math.min(page * TABLE_PAGE_SIZE, total);

  return (
    <BpTable<Volume>
      data={rows}
      columns={volumeColumns}
      getRowId={(row) => row.id}
      isLoading={isLoading}
      name="Volumes"
      totalCount={total}
      details={`Mock API fetch on page change (${TABLE_PAGE_SIZE} rows per page).`}
      pagination={{
        start,
        end,
        total,
        page,
        onFirstPage: () => setPage(1),
        onPreviousPage: () => setPage((current) => Math.max(1, current - 1)),
        onNextPage: () => setPage((current) => Math.min(totalPages, current + 1)),
        onLastPage: () => setPage(totalPages),
      }}
    />
  );
};

