      title: "Focused action · filled",
      props: {
        label: "Frequency",
        defaultValue: "10",
        state: "focus-action" as const,
        selectionValue: "per day",
      },
    },
    {
      title: "Hover input · empty",
      props: {
        label: "Capacity",
        placeholder: "Enter capacity",
        state: "hover-input" as const,
        selectionValue: "GiB",
      },
    },
    {
      title: "Hover action · filled",
      props: {
        label: "Memory",
        defaultValue: "8",
        state: "hover-action" as const,
        selectionValue: "GiB",
      },
    },
    {
      title: "Error · filled",
      props: {
        label: "Memory",
        defaultValue: "0",
        hasError: true,
        messageType: "error" as const,
        message: "Must be greater than zero",
        selectionValue: "GiB",
      },
    },
    {
      title: "Error · hover",
      props: {
        label: "Memory",
        defaultValue: "0",
        state: "hover-input" as const,
        hasError: true,
        messageType: "error" as const,
        message: "Must be greater than zero",
        selectionValue: "GiB",
      },
    },
    {
      title: "Error · empty",
      props: {
        label: "Timeout",
        placeholder: "Required",
        hasError: true,
        messageType: "error" as const,
        message: "Required",
        selectionValue: "seconds",
      },
    },
    {
      title: "Disabled · filled",
      props: {
        label: "Legacy limit",
        defaultValue: "2048",
        disabled: true,
        selectionValue: "MiB",
      },
    },
    {
      title: "Read only · filled",
      props: { label: "Disk size", defaultValue: "1", readOnly: true, selectionValue: "TB" },
    },
  ] as const;

  return (
    <div
      style={{
        padding: "32px",
        width: "fit-content",
        background: "var(--field-bg-disabled)",
      }}
    >
      <h3 style={{ margin: "0 0 8px 0" }}>Text input field with selection — gallery</h3>
      <div style={{ marginBottom: "20px", fontSize: "12px" }}>
        Rows: variant combinations (each row uses a different selection value). Columns:
        decoration overrides.
      </div>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "200px repeat(4, 384px)",
          gap: "16px 24px",
        }}
      >
        <div />
        {columns.map((column) => (
          <div key={column.key} style={{ fontSize: "12px", fontWeight: 600 }}>
            {column.title}
          </div>
        ))}
        {rows.map((row) => (
          <div key={row.title} style={{ display: "contents" }}>
            <div style={{ fontSize: "12px", paddingTop: "20px" }}>{row.title}</div>
            {columns.map((column) => {
              const hiddenLabelProps =
                column.key === "nolabel" && typeof row.props.label === "string"
                  ? { "aria-label": row.props.label }
                  : {};

              return (
                <FieldShowcase key={`${row.title}-${column.key}`}>
                  <BpTextFieldWithSelection
                    {...row.props}
                    {...column.props}
                    {...hiddenLabelProps}
                  />
                </FieldShowcase>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
};

